import{_ as r,o as t,c as a,a2 as s}from"./chunks/framework.DomDLpZJ.js";const d=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),o={name:"changelog.md"};function i(l,e,n,c,f,b){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Release notes for ktor-svelte 0.12.0 and every version before it. Each release is also on <a href="https://github.com/nijasc/ktor-svelte/releases" target="_blank" rel="noreferrer">GitHub</a>.</p><h2 id="_0-12-0" tabindex="-1">0.12.0 <a class="header-anchor" href="#_0-12-0" aria-label="Permalink to &quot;0.12.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-12, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.12.0">GitHub release</a></p><div><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>brand ktor-svelte with Kotlin and SvelteKit colors (<a href="https://github.com/nijasc/ktor-svelte/commit/f4b0a6d78850addb48139d4d0c232fd5bf1b80e8" target="_blank" rel="noreferrer">f4b0a6d</a>)</li><li><strong>gradle-plugin:</strong> add frontend debugging and one-click dev and debug run configurations (<a href="https://github.com/nijasc/ktor-svelte/commit/cae6d224b3d4c4a601ef8d357760aba24fd32426" target="_blank" rel="noreferrer">cae6d22</a>)</li><li><strong>gradle-plugin:</strong> clickable file links in the svelteDevAll console (<a href="https://github.com/nijasc/ktor-svelte/commit/5063c48be9ea655b0fd55eb5ee455c3d596c731a" target="_blank" rel="noreferrer">5063c48</a>)</li><li><strong>gradle-plugin:</strong> make compiler errors and browser stack traces clickable in the dev console (<a href="https://github.com/nijasc/ktor-svelte/commit/5730eb83d7c4ebe7193c198b02510604b2b3f238" target="_blank" rel="noreferrer">5730eb8</a>)</li><li><strong>gradle-plugin:</strong> run configurations for frontend debugging and one-click dev and debug (<a href="https://github.com/nijasc/ktor-svelte/commit/aa84844599c7336a431eba1128e77873dc9af816" target="_blank" rel="noreferrer">aa84844</a>)</li><li><strong>gradle-plugin:</strong> set up IntelliJ automatically for new projects (<a href="https://github.com/nijasc/ktor-svelte/commit/3cbd8ff5f4a4dcde9012d45be1f9b09b2b4bcd4f" target="_blank" rel="noreferrer">3cbd8ff</a>)</li><li><strong>gradle-plugin:</strong> set up IntelliJ automatically for new projects (<a href="https://github.com/nijasc/ktor-svelte/commit/bfbb359cbec7edee618411963eb71b02a7640cfc" target="_blank" rel="noreferrer">bfbb359</a>)</li></ul></div><h2 id="_0-11-0" tabindex="-1">0.11.0 <a class="header-anchor" href="#_0-11-0" aria-label="Permalink to &quot;0.11.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-12, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.11.0">GitHub release</a>, <a href="./migrations/0.11">upgrade guide</a></p><div><h3 id="⚠-breaking-changes" tabindex="-1">⚠ BREAKING CHANGES <a class="header-anchor" href="#⚠-breaking-changes" aria-label="Permalink to &quot;⚠ BREAKING CHANGES&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> imports of generated AppTheme, LucideIcon, Messages, theme and messages change from ktorsvelte to io.github.nijasc.ktorsvelte. Set libraries { generatedPackage = &quot;ktorsvelte&quot; } to keep the old package.</li></ul><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>example:</strong> import generated Kotlin from io.github.nijasc.ktorsvelte (<a href="https://github.com/nijasc/ktor-svelte/commit/39f936414507dcd1194a9d9b0159875b5d5e55d8" target="_blank" rel="noreferrer">39f9364</a>)</li><li><strong>example:</strong> preload page data on link hover (<a href="https://github.com/nijasc/ktor-svelte/commit/f9df17b1beac61a0540c6dd98e4f500f1f6745e5" target="_blank" rel="noreferrer">f9df17b</a>)</li><li><strong>example:</strong> ship only the icons the notes app uses (<a href="https://github.com/nijasc/ktor-svelte/commit/e674c995090883e32ac7e9164f091782a83179c7" target="_blank" rel="noreferrer">e674c99</a>)</li><li><strong>example:</strong> show an optimized image on the about page (<a href="https://github.com/nijasc/ktor-svelte/commit/1ec4b19a425a7c7eea02c7400214236d08a5a63d" target="_blank" rel="noreferrer">1ec4b19</a>)</li><li><strong>example:</strong> show API errors as toasts in the notes app (<a href="https://github.com/nijasc/ktor-svelte/commit/11c3716cdc37979d66c3685fc2d46e2af8e1b4f8" target="_blank" rel="noreferrer">11c3716</a>)</li><li><strong>example:</strong> use the shadcn themes in the notes app (<a href="https://github.com/nijasc/ktor-svelte/commit/1ed64ee29f18d660b2119caefcd4fe8200cc68a5" target="_blank" rel="noreferrer">1ed64ee</a>)</li><li><strong>gradle-plugin:</strong> add shadcn light and dark DaisyUI themes (<a href="https://github.com/nijasc/ktor-svelte/commit/a41bf0b9b634142623be57601ca52c68131792dc" target="_blank" rel="noreferrer">a41bf0b</a>)</li><li><strong>gradle-plugin:</strong> add shadcn light and dark themes (<a href="https://github.com/nijasc/ktor-svelte/commit/9a39e3d03ea6a55da75750880a5e3a17ad69b0cc" target="_blank" rel="noreferrer">9a39e3d</a>)</li><li><strong>gradle-plugin:</strong> add svelteConfig to review and score the configuration (<a href="https://github.com/nijasc/ktor-svelte/commit/ce7e58e15471029a525f309b05b3262669694e80" target="_blank" rel="noreferrer">ce7e58e</a>)</li><li><strong>gradle-plugin:</strong> add svelteConfig to review, score and improve the configuration (<a href="https://github.com/nijasc/ktor-svelte/commit/afb66cfe01b7fcea462a51790092e488c61e7b6a" target="_blank" rel="noreferrer">afb66cf</a>)</li><li><strong>gradle-plugin:</strong> build only the Lucide icons the app uses (<a href="https://github.com/nijasc/ktor-svelte/commit/2f0b28c0de3f36c382b12079fba4d7e85377cf56" target="_blank" rel="noreferrer">2f0b28c</a>)</li><li><strong>gradle-plugin:</strong> build only the Lucide icons the app uses (<a href="https://github.com/nijasc/ktor-svelte/commit/cb1d88cf37b9401148840a9b9334511618f928ed" target="_blank" rel="noreferrer">cb1d88c</a>)</li><li><strong>gradle-plugin:</strong> download a pinned Bun with svelte.bunVersion (<a href="https://github.com/nijasc/ktor-svelte/commit/8988c587bf109b6e52766a8ebca19b93bb14f1fc" target="_blank" rel="noreferrer">8988c58</a>)</li><li><strong>gradle-plugin:</strong> download a pinned Bun with svelte.bunVersion (<a href="https://github.com/nijasc/ktor-svelte/commit/a29336389f4a442c9f2ba5b622c7f2c8b78d5951" target="_blank" rel="noreferrer">a293363</a>)</li><li><strong>gradle-plugin:</strong> generate Kotlin in io.github.nijasc.ktorsvelte instead of ktorsvelte (<a href="https://github.com/nijasc/ktor-svelte/commit/fa681b77742bcc8d318172a004f7fbce02ae80e3" target="_blank" rel="noreferrer">fa681b7</a>)</li><li><strong>gradle-plugin:</strong> hide Vite&#39;s copies of browser console messages in svelteDevAll (<a href="https://github.com/nijasc/ktor-svelte/commit/0aa93adbb117713b2f1ca7184807652209d1dcd6" target="_blank" rel="noreferrer">0aa93ad</a>)</li><li><strong>gradle-plugin:</strong> optimize images with an images() frontend library (<a href="https://github.com/nijasc/ktor-svelte/commit/856ee37a3034acae096d35872b2cde611a2413d9" target="_blank" rel="noreferrer">856ee37</a>)</li><li><strong>gradle-plugin:</strong> optimize images with images() (<a href="https://github.com/nijasc/ktor-svelte/commit/e4b2d3ad14c107b4084f9f72eba2d3f305228d17" target="_blank" rel="noreferrer">e4b2d3a</a>)</li><li><strong>gradle-plugin:</strong> preload page data on link hover in new projects (<a href="https://github.com/nijasc/ktor-svelte/commit/e07bd39f22750e34984af37ee20ae8693f8fcc36" target="_blank" rel="noreferrer">e07bd39</a>)</li><li><strong>gradle-plugin:</strong> regenerate i18n messages while svelteDev runs (<a href="https://github.com/nijasc/ktor-svelte/commit/5d0e26d062584f05da85b49d33436d39f1d9b916" target="_blank" rel="noreferrer">5d0e26d</a>)</li><li><strong>gradle-plugin:</strong> regenerate i18n messages while svelteDev runs (<a href="https://github.com/nijasc/ktor-svelte/commit/bf7b84b2adaa8c40d90a23da3c6c8f11b5f10eaf" target="_blank" rel="noreferrer">bf7b84b</a>)</li><li><strong>gradle-plugin:</strong> report Kotlin compile errors from svelteDevAll to the app (<a href="https://github.com/nijasc/ktor-svelte/commit/8e147b0896493bb78808e1a79407fd8c85175571" target="_blank" rel="noreferrer">8e147b0</a>)</li><li><strong>gradle-plugin:</strong> show and score the newer settings in svelteConfig (<a href="https://github.com/nijasc/ktor-svelte/commit/f8d5040683edaf748d08a5113c5584e2361a88ff" target="_blank" rel="noreferrer">f8d5040</a>)</li><li><strong>gradle-plugin:</strong> show and score the newer settings in svelteConfig (<a href="https://github.com/nijasc/ktor-svelte/commit/d286fe010a62efdcf75a9db02928e3c4883b5f4b" target="_blank" rel="noreferrer">d286fe0</a>)</li><li><strong>gradle-plugin:</strong> show app, Vite and Kotlin output of svelteDevAll in one clean format (<a href="https://github.com/nijasc/ktor-svelte/commit/fa6eb54f37f2b7a8aa179e8497fa1b80aa066649" target="_blank" rel="noreferrer">fa6eb54</a>)</li><li><strong>gradle-plugin:</strong> show failed API calls as toasts with toasts() (<a href="https://github.com/nijasc/ktor-svelte/commit/686b0f1aeabd6c6406e952f8bab778f3d99466ab" target="_blank" rel="noreferrer">686b0f1</a>)</li><li><strong>gradle-plugin:</strong> unified, readable output for svelteDevAll (<a href="https://github.com/nijasc/ktor-svelte/commit/fdbb518f7e49e4b0663d4f5cca0bf5894c6072b1" target="_blank" rel="noreferrer">fdbb518</a>)</li><li><strong>repo:</strong> publish a version catalog (<a href="https://github.com/nijasc/ktor-svelte/commit/b7ab3da0700bf515ed4e8e7e73be9734a75ef73d" target="_blank" rel="noreferrer">b7ab3da</a>)</li><li><strong>repo:</strong> publish a version catalog with matching Kotlin, Ktor and ktor-svelte versions (<a href="https://github.com/nijasc/ktor-svelte/commit/83b70c504343e92b9326c8b02ab56e7886b44b13" target="_blank" rel="noreferrer">83b70c5</a>)</li><li><strong>repo:</strong> start new projects with the shadcn themes (<a href="https://github.com/nijasc/ktor-svelte/commit/714b39ba596fd9899d1a0a2e58b621881da6ca37" target="_blank" rel="noreferrer">714b39b</a>)</li><li><strong>server:</strong> add a development panel with API calls, timings and validation errors (<a href="https://github.com/nijasc/ktor-svelte/commit/7f36e226e204f80532112200267cff8c6f52f8a5" target="_blank" rel="noreferrer">7f36e22</a>)</li><li><strong>server:</strong> add a development panel with recent API calls, timings and validation errors (<a href="https://github.com/nijasc/ktor-svelte/commit/7f85ec59beea8a680c6e7af44fc33337d90b2a81" target="_blank" rel="noreferrer">7f85ec5</a>)</li><li><strong>server:</strong> forward browser console output to the app log in development (<a href="https://github.com/nijasc/ktor-svelte/commit/f0f8d16ceb3bb45916d2d5cd2dc344ae9d5b0fea" target="_blank" rel="noreferrer">f0f8d16</a>)</li><li><strong>server:</strong> forward browser console output to the app log in development (<a href="https://github.com/nijasc/ktor-svelte/commit/acd2505864328cb3f00bba513ba3437cd9f5101c" target="_blank" rel="noreferrer">acd2505</a>)</li><li><strong>server:</strong> prefetch API data on hover through the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/9f32a1f794e236b754840eec41e2d6aafe9bc444" target="_blank" rel="noreferrer">9f32a1f</a>)</li><li><strong>server:</strong> prefetch API data on link hover (<a href="https://github.com/nijasc/ktor-svelte/commit/671eb304aabc9ef732d1283d877788cf99bdf27d" target="_blank" rel="noreferrer">671eb30</a>)</li><li><strong>server:</strong> report failed API calls to apiConfig.onError in the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/c20daa6a6fc61c4a4b8e3f32de16be57bbee5caa" target="_blank" rel="noreferrer">c20daa6</a>)</li><li><strong>server:</strong> report the effective Svelte settings when asked by the build (<a href="https://github.com/nijasc/ktor-svelte/commit/9be201147a7d28168874266370f0acfd37a6f29b" target="_blank" rel="noreferrer">9be2011</a>)</li><li><strong>server:</strong> serve a generated sitemap.xml and robots.txt (<a href="https://github.com/nijasc/ktor-svelte/commit/dfd4b3affe43b51073fffa3484d7f4f491a6856f" target="_blank" rel="noreferrer">dfd4b3a</a>)</li><li><strong>server:</strong> serve a generated sitemap.xml and robots.txt for the prerendered pages (<a href="https://github.com/nijasc/ktor-svelte/commit/9d8fc558e7d965a5474314ff09bcab16a40cc161" target="_blank" rel="noreferrer">9d8fc55</a>)</li><li><strong>server:</strong> serve a ktor-svelte favicon until the app has its own (<a href="https://github.com/nijasc/ktor-svelte/commit/643acf135a899b2a824a333840da72a9bf4ed280" target="_blank" rel="noreferrer">643acf1</a>)</li><li><strong>server:</strong> serve a ktor-svelte favicon until the app has its own (<a href="https://github.com/nijasc/ktor-svelte/commit/10bd129328c8dc5f433b4b50e8b03791265a37b1" target="_blank" rel="noreferrer">10bd129</a>)</li><li><strong>server:</strong> show Kotlin compile errors in the browser during development (<a href="https://github.com/nijasc/ktor-svelte/commit/59cebd8ce4d558e31f78fd6b1a3e51e909b8e2e8" target="_blank" rel="noreferrer">59cebd8</a>)</li><li>show failed API calls as toasts with toasts() (<a href="https://github.com/nijasc/ktor-svelte/commit/3dd2c3ad9acc9eeeb0e921fe49429bde0689ca14" target="_blank" rel="noreferrer">3dd2c3a</a>)</li><li>show Kotlin compile errors in the browser overlay (<a href="https://github.com/nijasc/ktor-svelte/commit/ef9a2df00e62ab51bbba95aed5d3c802a290a7a5" target="_blank" rel="noreferrer">ef9a2df</a>)</li></ul><h3 id="bug-fixes" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>make the 0.11.0 release checks pass (<a href="https://github.com/nijasc/ktor-svelte/commit/dc9bb79b2267b30855c1a1e4c8c672f950f4f028" target="_blank" rel="noreferrer">dc9bb79</a>)</li><li><strong>repo:</strong> check settings snippets and version catalog aliases in the docs (<a href="https://github.com/nijasc/ktor-svelte/commit/d8963183feb2207bfda308195e592fe68bc6f8b5" target="_blank" rel="noreferrer">d896318</a>)</li><li><strong>repo:</strong> make the docs snippet check understand the version catalog (<a href="https://github.com/nijasc/ktor-svelte/commit/2c085901cd4c64b00e48dd0d501de0bb5e2ec06a" target="_blank" rel="noreferrer">2c08590</a>)</li><li><strong>repo:</strong> sync frontend libraries after the setup script writes its pages (<a href="https://github.com/nijasc/ktor-svelte/commit/89975b6e890afa3c8d3410b009d6d4ddc2133831" target="_blank" rel="noreferrer">89975b6</a>)</li><li><strong>server:</strong> answer 413 for an oversized chunked JSON body instead of 400 (<a href="https://github.com/nijasc/ktor-svelte/commit/d73adbb96422c730c6d19eeb42e8cdc346edd839" target="_blank" rel="noreferrer">d73adbb</a>)</li><li><strong>server:</strong> ignore lifecycle events of an application Ktor has reloaded (<a href="https://github.com/nijasc/ktor-svelte/commit/961933929551bfd930bb89858cebb506a7dd442b" target="_blank" rel="noreferrer">9619339</a>)</li><li><strong>server:</strong> recognise local clients by IP and stop reverse DNS lookups (<a href="https://github.com/nijasc/ktor-svelte/commit/53e1554de4746855c0395085a4117e57bf931ca7" target="_blank" rel="noreferrer">53e1554</a>)</li><li><strong>server:</strong> recognise local clients by IP and stop reverse DNS lookups for rate limits (<a href="https://github.com/nijasc/ktor-svelte/commit/4b4e9ab52049cacdfc9b172674d7f9ede95707fb" target="_blank" rel="noreferrer">4b4e9ab</a>)</li><li><strong>server:</strong> stop handling lifecycle events of an application Ktor has reloaded (<a href="https://github.com/nijasc/ktor-svelte/commit/c93b5d551ca3c4beca1008da2aa5e20c30dfc014" target="_blank" rel="noreferrer">c93b5d5</a>)</li></ul></div><h2 id="_0-10-1" tabindex="-1">0.10.1 <a class="header-anchor" href="#_0-10-1" aria-label="Permalink to &quot;0.10.1&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-11, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.10.1">GitHub release</a></p><div><h3 id="bug-fixes-1" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-1" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> update the API dump so the release can be published (<a href="https://github.com/nijasc/ktor-svelte/commit/b7216ff578693dac4431f33af523add891cf493d" target="_blank" rel="noreferrer">b7216ff</a>)</li><li><strong>gradle-plugin:</strong> update the API dump so the release can be published (<a href="https://github.com/nijasc/ktor-svelte/commit/1b6e9474a1a3d1dfd11023f52e89e3250df2fee8" target="_blank" rel="noreferrer">1b6e947</a>)</li></ul></div><h2 id="_0-10-0" tabindex="-1">0.10.0 <a class="header-anchor" href="#_0-10-0" aria-label="Permalink to &quot;0.10.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-11, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.10.0">GitHub release</a>, <a href="./migrations/0.10">upgrade guide</a></p><div><h3 id="features-2" tabindex="-1">Features <a class="header-anchor" href="#features-2" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>example:</strong> add a typed activity feed built from a sealed class (<a href="https://github.com/nijasc/ktor-svelte/commit/3204c9859f60fcab1d3405d026911cd0dddec77f" target="_blank" rel="noreferrer">3204c98</a>)</li><li><strong>example:</strong> describe the attachments route (<a href="https://github.com/nijasc/ktor-svelte/commit/922e3a133df9aca1acff0d5a8f0e8b259b0c892f" target="_blank" rel="noreferrer">922e3a1</a>)</li><li><strong>gradle-plugin:</strong> open the browser when svelteDevAll is ready (<a href="https://github.com/nijasc/ktor-svelte/commit/97b4232832984644079351883eb78bc44a48d908" target="_blank" rel="noreferrer">97b4232</a>)</li><li><strong>gradle-plugin:</strong> suggest the closest setting for a misspelled Groovy DSL property (<a href="https://github.com/nijasc/ktor-svelte/commit/0b64cd2cb85fd0ba00725f3feb3eaebdea3ea1be" target="_blank" rel="noreferrer">0b64cd2</a>)</li><li><strong>gradle-plugin:</strong> suggest the closest setting name in the Groovy DSL (<a href="https://github.com/nijasc/ktor-svelte/commit/16632b5020119ad74afacdaf4c09b67b08745049" target="_blank" rel="noreferrer">16632b5</a>)</li><li><strong>gradle-plugin:</strong> svelteDevAll opens the browser (<a href="https://github.com/nijasc/ktor-svelte/commit/bb0717822bb9828f78a0cacfd5d5c41c7be38810" target="_blank" rel="noreferrer">bb07178</a>)</li><li><strong>server:</strong> build fingerprint header and onNewBuild (<a href="https://github.com/nijasc/ktor-svelte/commit/d7f139748d554751fdb2eacdfd9e4bbaa09b0b68" target="_blank" rel="noreferrer">d7f1397</a>)</li><li><strong>server:</strong> exhaustive match for sealed class unions (<a href="https://github.com/nijasc/ktor-svelte/commit/0629719627b6e4acf53791eb721d245a5e12c881" target="_blank" rel="noreferrer">0629719</a>)</li><li><strong>server:</strong> generate types and an exhaustive match() for sealed class unions (<a href="https://github.com/nijasc/ktor-svelte/commit/440676c69c7b5e824ff95ab618542519739708b2" target="_blank" rel="noreferrer">440676c</a>)</li><li><strong>server:</strong> inline publicConfig into pages (<a href="https://github.com/nijasc/ktor-svelte/commit/aa212a7d666263448f11519b9843c06d219e763d" target="_blank" rel="noreferrer">aa212a7</a>)</li><li><strong>server:</strong> inline publicConfig into served pages and read it synchronously in the client (<a href="https://github.com/nijasc/ktor-svelte/commit/06c5ca8ad09589f03c77cc2177ef7000475fdb0b" target="_blank" rel="noreferrer">06c5ca8</a>)</li><li><strong>server:</strong> JSDoc from route descriptions (<a href="https://github.com/nijasc/ktor-svelte/commit/5b3c20592c5b3d8ab3681ea0b9e948a8ac015140" target="_blank" rel="noreferrer">5b3c205</a>)</li><li><strong>server:</strong> latest() cancels superseded requests (<a href="https://github.com/nijasc/ktor-svelte/commit/0ad41d90aaa029fb54b971ec1cc88d1b93d00944" target="_blank" rel="noreferrer">0ad41d9</a>)</li><li><strong>server:</strong> log the active security and dev settings at startup in development (<a href="https://github.com/nijasc/ktor-svelte/commit/6dfcd1cc7b8d105a3480d931a8f06b11d500a480" target="_blank" rel="noreferrer">6dfcd1c</a>)</li><li><strong>server:</strong> read the inlined publicConfig synchronously in the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/109795ffc20fbb74c7539af7a4df049d529e61a7" target="_blank" rel="noreferrer">109795f</a>)</li><li><strong>server:</strong> reload publicConfig in development (<a href="https://github.com/nijasc/ktor-svelte/commit/b947d5c4dab46f96cb349bec920c3147c8fb84de" target="_blank" rel="noreferrer">b947d5c</a>)</li><li><strong>server:</strong> reload publicConfig on every request in development (<a href="https://github.com/nijasc/ktor-svelte/commit/748f0714180a009b5eb6877f5342127f7c7b0402" target="_blank" rel="noreferrer">748f071</a>)</li><li><strong>server:</strong> request timeouts in the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/35811f6277b8df508683063586d999cef08145e7" target="_blank" rel="noreferrer">35811f6</a>)</li><li><strong>server:</strong> route table in development (<a href="https://github.com/nijasc/ktor-svelte/commit/bce3b17e3266777becc30c2ea9dd55516c34813d" target="_blank" rel="noreferrer">bce3b17</a>)</li><li><strong>server:</strong> serve a route table of Ktor routes and pages in development (<a href="https://github.com/nijasc/ktor-svelte/commit/ef87721f76186dbeab441906487a43b56e066886" target="_blank" rel="noreferrer">ef87721</a>)</li><li><strong>server:</strong> settings summary at startup in development (<a href="https://github.com/nijasc/ktor-svelte/commit/610ee4ab0bfc0a9d69026516f8987d6799373553" target="_blank" rel="noreferrer">610ee4a</a>)</li><li><strong>server:</strong> turn route summaries and descriptions into JSDoc in the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/37cc6fec0feef02cb47fcd1256e2b18e1626bd8b" target="_blank" rel="noreferrer">37cc6fe</a>)</li><li><strong>server:</strong> warn at startup when a Ktor route hides a frontend page (<a href="https://github.com/nijasc/ktor-svelte/commit/bbf906196ebe9188739a733b4da21d8f4ccd66c8" target="_blank" rel="noreferrer">bbf9061</a>)</li><li><strong>server:</strong> warn when a Ktor route hides a page (<a href="https://github.com/nijasc/ktor-svelte/commit/e99a97346125b0a873b790184ac17c6d641e8b50" target="_blank" rel="noreferrer">e99a973</a>)</li></ul><h3 id="bug-fixes-2" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-2" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> stop starting the package manager to read its version (<a href="https://github.com/nijasc/ktor-svelte/commit/b3a5800d81b643be5b4cd57c74313458afa58888" target="_blank" rel="noreferrer">b3a5800</a>)</li><li><strong>gradle-plugin:</strong> stop starting the package manager to read its version (<a href="https://github.com/nijasc/ktor-svelte/commit/edb08b12be16793e40fc7d4e365ed88914a14b83" target="_blank" rel="noreferrer">edb08b1</a>)</li><li><strong>server:</strong> never serve the SPA fallback for unknown /_ktor-svelte paths (<a href="https://github.com/nijasc/ktor-svelte/commit/a24aa9d86473404281dfdec1438e6f741786b8e5" target="_blank" rel="noreferrer">a24aa9d</a>)</li></ul></div><h2 id="_0-9-0" tabindex="-1">0.9.0 <a class="header-anchor" href="#_0-9-0" aria-label="Permalink to &quot;0.9.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-11, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.9.0">GitHub release</a>, <a href="./migrations/0.9">upgrade guide</a></p><div><h3 id="features-3" tabindex="-1">Features <a class="header-anchor" href="#features-3" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>CSP script hashes computed at build time (<a href="https://github.com/nijasc/ktor-svelte/commit/578d245db5a9b1975fdc935d857c7af7159a7c1d" target="_blank" rel="noreferrer">578d245</a>)</li><li><strong>gradle-plugin:</strong> store the inline script hashes of each page in the manifest (<a href="https://github.com/nijasc/ktor-svelte/commit/e4964d70c8b87aaf51ea4ff345ec446afbfc57a1" target="_blank" rel="noreferrer">e4964d7</a>)</li><li>link error messages to the docs site (<a href="https://github.com/nijasc/ktor-svelte/commit/5c8214a88179fa316e4a7a3da6d782b6acf6ecf1" target="_blank" rel="noreferrer">5c8214a</a>)</li><li>request IDs from the client to the server logs (<a href="https://github.com/nijasc/ktor-svelte/commit/63bb0421ad690fc8f6abfd66eb89d32d51652da2" target="_blank" rel="noreferrer">63bb042</a>)</li><li><strong>server:</strong> add sliding window and token bucket rate limits (<a href="https://github.com/nijasc/ktor-svelte/commit/84f8047141da77a6a174f3a6317065520d5153b5" target="_blank" rel="noreferrer">84f8047</a>)</li><li><strong>server:</strong> answer Range requests for files in the build (<a href="https://github.com/nijasc/ktor-svelte/commit/03c52d3f22356e1703fb0521fbabef196c8cd338" target="_blank" rel="noreferrer">03c52d3</a>)</li><li><strong>server:</strong> configurable rate limit keys (<a href="https://github.com/nijasc/ktor-svelte/commit/8e97973179a33e2ce5dc538d555712bee6677d00" target="_blank" rel="noreferrer">8e97973</a>)</li><li><strong>server:</strong> count origin, body limit and rate limit refusals (<a href="https://github.com/nijasc/ktor-svelte/commit/3e157ddbdf76f98ab315a373527d653e78261ae4" target="_blank" rel="noreferrer">3e157dd</a>)</li><li><strong>server:</strong> count security refusals (<a href="https://github.com/nijasc/ktor-svelte/commit/b7fe2dff4b70057574938783acf351694e550198" target="_blank" rel="noreferrer">b7fe2df</a>)</li><li><strong>server:</strong> give every request an ID, echo it back and log it with unhandled errors (<a href="https://github.com/nijasc/ktor-svelte/commit/3a0da8d9055348885b98f1f1cb521733669bfbb0" target="_blank" rel="noreferrer">3a0da8d</a>)</li><li><strong>server:</strong> JSON nesting and string limits (<a href="https://github.com/nijasc/ktor-svelte/commit/c60e96c97ceb093f96a73c10c1f5dcffc608bdf1" target="_blank" rel="noreferrer">c60e96c</a>)</li><li><strong>server:</strong> let apps choose the rate limit key, globally or per named limit (<a href="https://github.com/nijasc/ktor-svelte/commit/34b9db6ff37f6e70d45531659134b3ab5e96f89b" target="_blank" rel="noreferrer">34b9db6</a>)</li><li><strong>server:</strong> log slow API calls with their route in development (<a href="https://github.com/nijasc/ktor-svelte/commit/39878a610e759b0ca768160bfa12b4c132c55799" target="_blank" rel="noreferrer">39878a6</a>)</li><li><strong>server:</strong> log slow API calls with their route source in development (<a href="https://github.com/nijasc/ktor-svelte/commit/03fef51383b9754c45e97ed3849fe7e716a2e247" target="_blank" rel="noreferrer">03fef51</a>)</li><li><strong>server:</strong> log the ktor-svelte version and the frontend build fingerprint at startup (<a href="https://github.com/nijasc/ktor-svelte/commit/69eec03df3633e4f19aff75072114c7f9fdc3b02" target="_blank" rel="noreferrer">69eec03</a>)</li><li><strong>server:</strong> log version and build fingerprint at startup (<a href="https://github.com/nijasc/ktor-svelte/commit/240802e38bc651c5a25e13923583c8b9e80d1b9b" target="_blank" rel="noreferrer">240802e</a>)</li><li><strong>server:</strong> prepare ETag, Cache-Control and content type once per file (<a href="https://github.com/nijasc/ktor-svelte/commit/111b1f5bb74128ae54915bde5bf157b7c987959e" target="_blank" rel="noreferrer">111b1f5</a>)</li><li><strong>server:</strong> prepare static response headers once per file (<a href="https://github.com/nijasc/ktor-svelte/commit/97a02d96982c1e568865183545e2e34a5d64b828" target="_blank" rel="noreferrer">97a02d9</a>)</li><li><strong>server:</strong> Range requests for build files (<a href="https://github.com/nijasc/ktor-svelte/commit/2142f6041c2767e30905e72661d1572f3b749791" target="_blank" rel="noreferrer">2142f60</a>)</li><li><strong>server:</strong> refuse API JSON that is nested too deep or has overly long strings (<a href="https://github.com/nijasc/ktor-svelte/commit/fc8ab835c003e6cb4f9cfceeafdf8d68b5877e66" target="_blank" rel="noreferrer">fc8ab83</a>)</li><li><strong>server:</strong> send a request ID from the generated client and expose it on ApiError (<a href="https://github.com/nijasc/ktor-svelte/commit/c7439042d4b3d763ea0b073383f46f89e154098f" target="_blank" rel="noreferrer">c743904</a>)</li><li><strong>server:</strong> sliding window and token bucket rate limits (<a href="https://github.com/nijasc/ktor-svelte/commit/363221cfb0a4c6303f2cabfabfcd93eda2ef6908" target="_blank" rel="noreferrer">363221c</a>)</li><li><strong>server:</strong> use script hashes from the manifest instead of reading pages (<a href="https://github.com/nijasc/ktor-svelte/commit/55762e8af61ab0fc0bb22bacd0dd1c3c5c096a25" target="_blank" rel="noreferrer">55762e8</a>)</li></ul><h3 id="bug-fixes-3" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-3" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>repo:</strong> CI change detection failed with permission denied (<a href="https://github.com/nijasc/ktor-svelte/commit/df3be0ec0590bfee16783c73da6e03460cd301d6" target="_blank" rel="noreferrer">df3be0e</a>)</li><li><strong>repo:</strong> make the CI change detection script runnable (<a href="https://github.com/nijasc/ktor-svelte/commit/dbdfb98a82e40ba76b33a3df20068470f43e2933" target="_blank" rel="noreferrer">dbdfb98</a>)</li><li><strong>server:</strong> 405 with Allow for wrong methods on frontend paths (<a href="https://github.com/nijasc/ktor-svelte/commit/37e5a6b78e247c41970a62ba2317329cff8269c5" target="_blank" rel="noreferrer">37e5a6b</a>)</li><li><strong>server:</strong> answer 405 with Allow for wrong methods on frontend paths (<a href="https://github.com/nijasc/ktor-svelte/commit/a3ace6af15d98d919cc7d51274b21b31c46a6466" target="_blank" rel="noreferrer">a3ace6a</a>)</li><li><strong>server:</strong> leave the allowedOrigins hint out of 403 responses in production (<a href="https://github.com/nijasc/ktor-svelte/commit/1ca325725b7b968eebe25ec6537c0d970ce35b5b" target="_blank" rel="noreferrer">1ca3257</a>)</li><li><strong>server:</strong> never serve the SPA fallback for missing .well-known paths (<a href="https://github.com/nijasc/ktor-svelte/commit/2b6748b9015110bf4ca7ad89f5a6b01becab727c" target="_blank" rel="noreferrer">2b6748b</a>)</li><li><strong>server:</strong> no allowedOrigins hint in production 403s (<a href="https://github.com/nijasc/ktor-svelte/commit/20bb802e0ad7278477e1c07d123ef0e3f49fd1af" target="_blank" rel="noreferrer">20bb802</a>)</li><li><strong>server:</strong> no SPA fallback for missing .well-known paths (<a href="https://github.com/nijasc/ktor-svelte/commit/2b584f7329191810627462114d285df999abb799" target="_blank" rel="noreferrer">2b584f7</a>)</li></ul></div><h2 id="_0-8-0" tabindex="-1">0.8.0 <a class="header-anchor" href="#_0-8-0" aria-label="Permalink to &quot;0.8.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-11, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.8.0">GitHub release</a>, <a href="./migrations/0.8">upgrade guide</a></p><div><h3 id="features-4" tabindex="-1">Features <a class="header-anchor" href="#features-4" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>server:</strong> compress API responses by default (<a href="https://github.com/nijasc/ktor-svelte/commit/7ea5871ae5b74ec7aced88ecd220a0c80707e69f" target="_blank" rel="noreferrer">7ea5871</a>)</li><li><strong>server:</strong> compress API responses by default, with zstd when its module is on the classpath (<a href="https://github.com/nijasc/ktor-svelte/commit/d681725c7a668b9264e8198d13be14249e77fb9a" target="_blank" rel="noreferrer">d681725</a>)</li></ul></div><h2 id="_0-7-0" tabindex="-1">0.7.0 <a class="header-anchor" href="#_0-7-0" aria-label="Permalink to &quot;0.7.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-11, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.7.0">GitHub release</a>, <a href="./migrations/0.7">upgrade guide</a></p><div><h3 id="features-5" tabindex="-1">Features <a class="header-anchor" href="#features-5" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>example:</strong> accept note attachments as multipart uploads (<a href="https://github.com/nijasc/ktor-svelte/commit/d161eaa04edba571545b25125db900f04709062d" target="_blank" rel="noreferrer">d161eaa</a>)</li><li><strong>example:</strong> page through notes with Page and a cursor (<a href="https://github.com/nijasc/ktor-svelte/commit/80df5172cbb33529c5702dcafa89cc51bf61e454" target="_blank" rel="noreferrer">80df517</a>)</li><li><strong>example:</strong> show title errors with the field action on both note forms (<a href="https://github.com/nijasc/ktor-svelte/commit/1f69c57047f6586636b7897f9295c61cd48498f4" target="_blank" rel="noreferrer">1f69c57</a>)</li><li><strong>gradle-plugin:</strong> add svelteLiveTemplates with IntelliJ live templates for routes, DTOs and client calls (<a href="https://github.com/nijasc/ktor-svelte/commit/f3443655033f3f3b5b27467331106e420d539bf8" target="_blank" rel="noreferrer">f344365</a>)</li><li><strong>gradle-plugin:</strong> bundle .zst variants as zstd encodings (<a href="https://github.com/nijasc/ktor-svelte/commit/32bbf14098139aac5d527b90e7df9abf16dfbd4d" target="_blank" rel="noreferrer">32bbf14</a>)</li><li><strong>gradle-plugin:</strong> deepClean also deletes .gradle and .kotlin (<a href="https://github.com/nijasc/ktor-svelte/commit/b638076873e4da831de7a4ba0e942f591a8a8b24" target="_blank" rel="noreferrer">b638076</a>)</li><li><strong>gradle-plugin:</strong> deepClean also deletes the project&#39;s .gradle and .kotlin directories (<a href="https://github.com/nijasc/ktor-svelte/commit/affceae6c51cff18e07e94227b2958b7fedc82c3" target="_blank" rel="noreferrer">affceae</a>)</li><li><strong>gradle-plugin:</strong> editorconfig for new frontends (<a href="https://github.com/nijasc/ktor-svelte/commit/3f6c0f5532e049906286f1fd14329cdfec210810" target="_blank" rel="noreferrer">3f6c0f5</a>)</li><li><strong>gradle-plugin:</strong> gzip text files the frontend build left uncompressed (<a href="https://github.com/nijasc/ktor-svelte/commit/0f2a12917a8060048868d34074620bc1bea66d92" target="_blank" rel="noreferrer">0f2a129</a>)</li><li><strong>gradle-plugin:</strong> hide frontend install and build output unless it fails or svelte.verbose is set (<a href="https://github.com/nijasc/ktor-svelte/commit/9a8e1d3bdfc5c71477fbd79944ca4c3470e00e86" target="_blank" rel="noreferrer">9a8e1d3</a>)</li><li><strong>gradle-plugin:</strong> IntelliJ live templates (<a href="https://github.com/nijasc/ktor-svelte/commit/711f028f5038cffa65f86b5956b2dab879d356e5" target="_blank" rel="noreferrer">711f028</a>)</li><li><strong>gradle-plugin:</strong> link build error messages to their README section (<a href="https://github.com/nijasc/ktor-svelte/commit/09064e837877826cfdf78742936c70746dea9595" target="_blank" rel="noreferrer">09064e8</a>)</li><li><strong>gradle-plugin:</strong> pass extra arguments to scripts with svelteRun --args (<a href="https://github.com/nijasc/ktor-svelte/commit/d6f177ba6e26030eed57130f41dc52a90bd962ca" target="_blank" rel="noreferrer">d6f177b</a>)</li><li><strong>gradle-plugin:</strong> precompress files the adapter left uncompressed (<a href="https://github.com/nijasc/ktor-svelte/commit/a0d9f9dcc4ced7f07be6f6bcbaa22d41f42351f3" target="_blank" rel="noreferrer">a0d9f9d</a>)</li><li><strong>gradle-plugin:</strong> print the app, API docs and Vite URLs when svelteDevAll is ready (<a href="https://github.com/nijasc/ktor-svelte/commit/3cffe399dd49f67c46d658da861e9d199a5850ab" target="_blank" rel="noreferrer">3cffe39</a>)</li><li><strong>gradle-plugin:</strong> quiet frontend output unless it fails (<a href="https://github.com/nijasc/ktor-svelte/commit/5a71731a6e4c6232bbda519eeafc15b408341c91" target="_blank" rel="noreferrer">5a71731</a>)</li><li><strong>gradle-plugin:</strong> svelteInit writes an .editorconfig for the frontend (<a href="https://github.com/nijasc/ktor-svelte/commit/838a4bb187f1b747e725aae8c46e696c67e122e2" target="_blank" rel="noreferrer">838a4bb</a>)</li><li><strong>gradle-plugin:</strong> svelteRun --args (<a href="https://github.com/nijasc/ktor-svelte/commit/60a847a21f7956ea902a4fc7bfa9aacfbd687604" target="_blank" rel="noreferrer">60a847a</a>)</li><li>link error messages to the docs page that explains them (<a href="https://github.com/nijasc/ktor-svelte/commit/87c1ea8bcaa922e35f1d0fadba3559c6491cb340" target="_blank" rel="noreferrer">87c1ea8</a>)</li><li>link error messages to the README (<a href="https://github.com/nijasc/ktor-svelte/commit/ed2dbd5b4751bff75149c510ce1674bb2d9c7ef9" target="_blank" rel="noreferrer">ed2dbd5</a>)</li><li>print the URLs when svelteDevAll is ready (<a href="https://github.com/nijasc/ktor-svelte/commit/b1f1173a15bcea16708fba906b712f4194544cfb" target="_blank" rel="noreferrer">b1f1173</a>)</li><li>serve zstd variants (<a href="https://github.com/nijasc/ktor-svelte/commit/a64ae14c17be12c7196f9e454f2ec5d5e0fc08c6" target="_blank" rel="noreferrer">a64ae14</a>)</li><li><strong>server:</strong> add an optional health endpoint for load balancers (<a href="https://github.com/nijasc/ktor-svelte/commit/96c45606d2f287147eaa54965afa1e46d909ff4f" target="_blank" rel="noreferrer">96c4560</a>)</li><li><strong>server:</strong> add Page and a typed pages() iterator to the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/421c2d2e7234666069ab8b595f00e16ba9814af6" target="_blank" rel="noreferrer">421c2d2</a>)</li><li><strong>server:</strong> apiWith(event) for SvelteKit load functions (<a href="https://github.com/nijasc/ktor-svelte/commit/91aece678d804a9b40f2e05d8171246f050a4139" target="_blank" rel="noreferrer">91aece6</a>)</li><li><strong>server:</strong> compute the CSP of every page once at startup (<a href="https://github.com/nijasc/ktor-svelte/commit/b297cf77e82f3028c71df372f4175a5cfc080449" target="_blank" rel="noreferrer">b297cf7</a>)</li><li><strong>server:</strong> declare errors from StatusPages with errorResponse so the generated ApiErrors include them (<a href="https://github.com/nijasc/ktor-svelte/commit/55e6eb20a98e9cc930f64ffbcddec1a102e59e53" target="_blank" rel="noreferrer">55e6eb2</a>)</li><li><strong>server:</strong> export each generated endpoint on its own so bundlers can drop unused ones (<a href="https://github.com/nijasc/ktor-svelte/commit/101d5249de529c3130530b6df3bf56a830fd85c7" target="_blank" rel="noreferrer">101d524</a>)</li><li><strong>server:</strong> file uploads with progress in the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/e8672f4a19914e393a857cc621969739fb3bfe88" target="_blank" rel="noreferrer">e8672f4</a>)</li><li><strong>server:</strong> generate a field action that applies bounds and shows validation errors next to inputs (<a href="https://github.com/nijasc/ktor-svelte/commit/255ad4235f5690867a9eb4dc3be0042aeca6ad06" target="_blank" rel="noreferrer">255ad42</a>)</li><li><strong>server:</strong> generate apiWith(event) so load functions use SvelteKit&#39;s fetch (<a href="https://github.com/nijasc/ktor-svelte/commit/e56c65a5fe0625e544ae57993bc2ae96963aa73c" target="_blank" rel="noreferrer">e56c65a</a>)</li><li><strong>server:</strong> let the generated client share identical GET requests in flight (<a href="https://github.com/nijasc/ktor-svelte/commit/83a706eb58e5efa8cb995cdc90091828f8e0aa51" target="_blank" rel="noreferrer">83a706e</a>)</li><li><strong>server:</strong> link runtime error messages to their README section (<a href="https://github.com/nijasc/ktor-svelte/commit/a5e75d510267f1baab0f4cea86adb64d4d254959" target="_blank" rel="noreferrer">a5e75d5</a>)</li><li><strong>server:</strong> log where the API docs are served in development (<a href="https://github.com/nijasc/ktor-svelte/commit/923bf7cc206b34319a645710ee96318df94d6f40" target="_blank" rel="noreferrer">923bf7c</a>)</li><li><strong>server:</strong> one export per generated endpoint (<a href="https://github.com/nijasc/ktor-svelte/commit/ccefd4f0038b98a4bf94c95043ba97d46084b467" target="_blank" rel="noreferrer">ccefd4f</a>)</li><li><strong>server:</strong> opt-in dedupe of in-flight GET requests (<a href="https://github.com/nijasc/ktor-svelte/commit/dc51d0995c21b4894d9b9d32f608f7333142b5f2" target="_blank" rel="noreferrer">dc51d09</a>)</li><li><strong>server:</strong> optional health endpoint (<a href="https://github.com/nijasc/ktor-svelte/commit/69b8da51cced2e2c1a4454f04cafa6d0508bf9b6" target="_blank" rel="noreferrer">69b8da5</a>)</li><li><strong>server:</strong> Page and typed pages() iterator (<a href="https://github.com/nijasc/ktor-svelte/commit/ad16f75a4c5f2e02cf829c74d22fda3320635b95" target="_blank" rel="noreferrer">ad16f75</a>)</li><li><strong>server:</strong> precompute page CSPs at startup (<a href="https://github.com/nijasc/ktor-svelte/commit/b463f70acd489bd38f977791caf5a9e99d43c89c" target="_blank" rel="noreferrer">b463f70</a>)</li><li><strong>server:</strong> rate limit API writes by default (<a href="https://github.com/nijasc/ktor-svelte/commit/73f55dc26a37a122b50ccee52e37d0216eeb27b2" target="_blank" rel="noreferrer">73f55dc</a>)</li><li><strong>server:</strong> rate limit writes to API paths per client by default, with named limits for login routes (<a href="https://github.com/nijasc/ktor-svelte/commit/31f1263a2b84d1d616f3310d514b152e5c645a07" target="_blank" rel="noreferrer">31f1263</a>)</li><li><strong>server:</strong> routes.json maps services to Kotlin routes (<a href="https://github.com/nijasc/ktor-svelte/commit/b9f90b7a6342619f73629e23fa37b6cb4ffd6df8" target="_blank" rel="noreferrer">b9f90b7</a>)</li><li><strong>server:</strong> serve zstd variants to browsers that accept them (<a href="https://github.com/nijasc/ktor-svelte/commit/52fc16c7abc620e26fc837812aa8d57edb2834f4" target="_blank" rel="noreferrer">52fc16c</a>)</li><li><strong>server:</strong> stream directory builds through a file channel (<a href="https://github.com/nijasc/ktor-svelte/commit/42e98bcd2fc275720b6c67c11c7a6c13a910a322" target="_blank" rel="noreferrer">42e98bc</a>)</li><li><strong>server:</strong> stream files from a build directory through a file channel (<a href="https://github.com/nijasc/ktor-svelte/commit/dd1800975dad574941c20db89136f5fdd215927a" target="_blank" rel="noreferrer">dd18009</a>)</li><li><strong>server:</strong> type multipart bodies as FormData and report upload progress (<a href="https://github.com/nijasc/ktor-svelte/commit/5ebd5cb5b304859c28baa72345c4c2f56e751209" target="_blank" rel="noreferrer">5ebd5cb</a>)</li><li><strong>server:</strong> typed errors from StatusPages via errorResponse (<a href="https://github.com/nijasc/ktor-svelte/commit/b834466a4f06ca99c7c8dfe6adb132fcd1d07bd2" target="_blank" rel="noreferrer">b834466</a>)</li><li><strong>server:</strong> use:field action for validation errors (<a href="https://github.com/nijasc/ktor-svelte/commit/e55db41da011b79b13e16acec1987af47809af3f" target="_blank" rel="noreferrer">e55db41</a>)</li><li><strong>server:</strong> write build/ktor-svelte/routes.json that maps each generated service to its Kotlin route (<a href="https://github.com/nijasc/ktor-svelte/commit/26bf718e144c602c2bbce1a8e185fa6172209b10" target="_blank" rel="noreferrer">26bf718</a>)</li></ul><h3 id="bug-fixes-4" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-4" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> add the missing editorconfig template file (<a href="https://github.com/nijasc/ktor-svelte/commit/fcc4d2e4b5510739b9c603ddbb756cca608facdd" target="_blank" rel="noreferrer">fcc4d2e</a>)</li><li><strong>gradle-plugin:</strong> deepClean deletes what it can of .gradle and .kotlin and warns about locked files (<a href="https://github.com/nijasc/ktor-svelte/commit/f706c3f5884e6b930d8aa50e27ea2dd702b879c3" target="_blank" rel="noreferrer">f706c3f</a>)</li><li><strong>gradle-plugin:</strong> deepClean on Windows (<a href="https://github.com/nijasc/ktor-svelte/commit/06c66a6f6eac197f1cc5f28123fe5759567f0a00" target="_blank" rel="noreferrer">06c66a6</a>)</li><li><strong>server:</strong> ktlint violations in RouteSources.kt (<a href="https://github.com/nijasc/ktor-svelte/commit/e96cf2f3dc562da5a8903f56fcee237b18b321c2" target="_blank" rel="noreferrer">e96cf2f</a>)</li><li><strong>server:</strong> satisfy ktlint in the route source reader (<a href="https://github.com/nijasc/ktor-svelte/commit/b905b34a8c6c5a13bda3d529704f6a169d4d7fba" target="_blank" rel="noreferrer">b905b34</a>)</li></ul></div><h2 id="_0-6-2" tabindex="-1">0.6.2 <a class="header-anchor" href="#_0-6-2" aria-label="Permalink to &quot;0.6.2&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-10, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.6.2">GitHub release</a></p><div><h3 id="bug-fixes-5" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-5" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>server:</strong> stop sending exception messages in production error responses (<a href="https://github.com/nijasc/ktor-svelte/commit/64df495e70114d8761f9054f88e6b2996b8ad07b" target="_blank" rel="noreferrer">64df495</a>)</li></ul></div><h2 id="_0-6-1" tabindex="-1">0.6.1 <a class="header-anchor" href="#_0-6-1" aria-label="Permalink to &quot;0.6.1&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-10, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.6.1">GitHub release</a></p><div><h3 id="bug-fixes-6" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-6" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> reject outputDir values that point outside the frontend on Windows or at the frontend itself (<a href="https://github.com/nijasc/ktor-svelte/commit/8e4b844e47c93181f0f8ec6ab3b467f8c3c980e5" target="_blank" rel="noreferrer">8e4b844</a>)</li><li><strong>server:</strong> check cross-site API requests for every method that is not safe (<a href="https://github.com/nijasc/ktor-svelte/commit/0cfb73634e7f79774499f63f626692a2bf1da83b" target="_blank" rel="noreferrer">0cfb736</a>)</li><li><strong>server:</strong> enforce schema bounds and Validated rules inside nested objects, maps, sealed types and received lists (<a href="https://github.com/nijasc/ktor-svelte/commit/3f9c4399d1147efe1ca0efd21077eb169154007b" target="_blank" rel="noreferrer">3f9c439</a>)</li><li><strong>server:</strong> escape line breaks and backslashes in generated TypeScript strings (<a href="https://github.com/nijasc/ktor-svelte/commit/78bf431d2d224479dca9e9676e8e5ec8e77bbe0b" target="_blank" rel="noreferrer">78bf431</a>)</li><li><strong>server:</strong> escape route paths in generated service URLs (<a href="https://github.com/nijasc/ktor-svelte/commit/4b8cb695c00a60df746d4ec5428fa21473f186fb" target="_blank" rel="noreferrer">4b8cb69</a>)</li><li><strong>server:</strong> hash build files as a stream instead of reading each one into memory (<a href="https://github.com/nijasc/ktor-svelte/commit/4d3b07430156a950443f25bfa8d5b8d9a470aaba" target="_blank" rel="noreferrer">4d3b074</a>)</li><li><strong>server:</strong> keep generated TypeScript identifiers off reserved words and module names (<a href="https://github.com/nijasc/ktor-svelte/commit/5cfa55ea68691f76a05173dc71f485e4489a59d4" target="_blank" rel="noreferrer">5cfa55e</a>)</li><li><strong>server:</strong> percent-encode the Location of trailing-slash redirects (<a href="https://github.com/nijasc/ktor-svelte/commit/6db27d77fd2085e03d675b18832ab2d5541dd7e3" target="_blank" rel="noreferrer">6db27d7</a>)</li><li><strong>server:</strong> percent-encode the Location of trailing-slash redirects (<a href="https://github.com/nijasc/ktor-svelte/commit/e114b68d8de4526ebc08672858b660218c70c205" target="_blank" rel="noreferrer">e114b68</a>)</li><li><strong>server:</strong> stop re-hashing every build file on each request in development (<a href="https://github.com/nijasc/ktor-svelte/commit/c951ac51c0f37e6cf0cfb3f8e6c0863461f20a8d" target="_blank" rel="noreferrer">c951ac5</a>)</li><li><strong>server:</strong> stop re-hashing the whole build on every request in development (<a href="https://github.com/nijasc/ktor-svelte/commit/10f2aeea58fbf985d3b8faa86f22302ec8e2d92a" target="_blank" rel="noreferrer">10f2aee</a>)</li><li><strong>server:</strong> treat proxied requests as remote for local-only endpoints (<a href="https://github.com/nijasc/ktor-svelte/commit/77f378a02fea259a072abb75aaaf8dff6151bc2c" target="_blank" rel="noreferrer">77f378a</a>)</li><li><strong>server:</strong> treat requests that came through a proxy as remote for the status endpoint and dev proxy (<a href="https://github.com/nijasc/ktor-svelte/commit/b3e5ec36130a4fe4fb81c86e1a339c1a28a25469" target="_blank" rel="noreferrer">b3e5ec3</a>)</li><li><strong>server:</strong> validate nested objects, maps, sealed types and received lists (<a href="https://github.com/nijasc/ktor-svelte/commit/352fa652064edcbd4fc0d4cf99d0518093f304ab" target="_blank" rel="noreferrer">352fa65</a>)</li></ul></div><h2 id="_0-6-0" tabindex="-1">0.6.0 <a class="header-anchor" href="#_0-6-0" aria-label="Permalink to &quot;0.6.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-10, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.6.0">GitHub release</a>, <a href="./migrations/0.6">upgrade guide</a></p><div><h3 id="features-6" tabindex="-1">Features <a class="header-anchor" href="#features-6" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>example:</strong> validate the new-note form instantly with the generated validate() (<a href="https://github.com/nijasc/ktor-svelte/commit/4f0e6a1b3b41557b268f0e99c352ef9f38abbb01" target="_blank" rel="noreferrer">4f0e6a1</a>)</li><li><strong>gradle-plugin:</strong> fail check when generated TypeScript is out of date (<a href="https://github.com/nijasc/ktor-svelte/commit/791423310b0bf379d4770523b3c6af38fdd4ead6" target="_blank" rel="noreferrer">7914233</a>)</li><li><strong>server:</strong> generate branded date types with safe parse helpers (<a href="https://github.com/nijasc/ktor-svelte/commit/489c4f8f7cc2a0947a17f09f18b9ab74a1bca446" target="_blank" rel="noreferrer">489c4f8</a>)</li><li><strong>server:</strong> generate branded date types with safe parse helpers (<a href="https://github.com/nijasc/ktor-svelte/commit/857db5919cdf41dc79d6c16f9b713078c45808a2" target="_blank" rel="noreferrer">857db59</a>)</li><li><strong>server:</strong> generate client-side validate() and required bounds from schema constraints (<a href="https://github.com/nijasc/ktor-svelte/commit/adcbb656914dd05c53891f21eab53849dca37969" target="_blank" rel="noreferrer">adcbb65</a>)</li><li><strong>server:</strong> reject cross-site API writes and oversized request bodies by default (<a href="https://github.com/nijasc/ktor-svelte/commit/0ef55537b15380032e01daa49ae8b3084ce8e515" target="_blank" rel="noreferrer">0ef5553</a>)</li><li><strong>server:</strong> send security headers and a strict build-derived CSP by default (<a href="https://github.com/nijasc/ktor-svelte/commit/aab69c36a49dd05b75396a8620051ad6c16da518" target="_blank" rel="noreferrer">aab69c3</a>)</li><li><strong>server:</strong> verify generated TypeScript without writing it (<a href="https://github.com/nijasc/ktor-svelte/commit/64386eaf77c95c1699d52cd6095e7c206ab25e41" target="_blank" rel="noreferrer">64386ea</a>)</li></ul></div><h2 id="_0-5-0" tabindex="-1">0.5.0 <a class="header-anchor" href="#_0-5-0" aria-label="Permalink to &quot;0.5.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-10, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.5.0">GitHub release</a></p><div><h3 id="features-7" tabindex="-1">Features <a class="header-anchor" href="#features-7" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> let a debugger attach to the app started by svelteDevAll (<a href="https://github.com/nijasc/ktor-svelte/commit/89145f870a1077eb0f409bfca783bda8d58f472d" target="_blank" rel="noreferrer">89145f8</a>)</li><li><strong>gradle-plugin:</strong> let a debugger attach to the app started by svelteDevAll (<a href="https://github.com/nijasc/ktor-svelte/commit/91c10125b733ec60d2a38f9e762aeb0759facaa2" target="_blank" rel="noreferrer">91c1012</a>)</li><li><strong>server:</strong> enforce JsonSchema bounds on received DTOs and generate them for forms (<a href="https://github.com/nijasc/ktor-svelte/commit/68844e217f5430dba2761606509e2f690f42dfb5" target="_blank" rel="noreferrer">68844e2</a>)</li><li><strong>server:</strong> enforce JsonSchema bounds on received DTOs and generate them for forms (<a href="https://github.com/nijasc/ktor-svelte/commit/b114bb1098e82e7c39f72d28ee06d0d951a0b5d1" target="_blank" rel="noreferrer">b114bb1</a>)</li><li><strong>server:</strong> generate empty() factories for TypeScript object types (<a href="https://github.com/nijasc/ktor-svelte/commit/d6a5803f35ffac05ac226fb3b68fbd5a3f477076" target="_blank" rel="noreferrer">d6a5803</a>)</li><li><strong>server:</strong> generate empty() factories for TypeScript object types (<a href="https://github.com/nijasc/ktor-svelte/commit/0a47635db83ae946c5b850f7403920733a2a52ce" target="_blank" rel="noreferrer">0a47635</a>)</li></ul><h3 id="bug-fixes-7" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-7" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> stop frontend tasks of one project from running at once (<a href="https://github.com/nijasc/ktor-svelte/commit/b08e90372c41106969d57d41b5c45ae44aa7efee" target="_blank" rel="noreferrer">b08e903</a>)</li></ul></div><h2 id="_0-4-0" tabindex="-1">0.4.0 <a class="header-anchor" href="#_0-4-0" aria-label="Permalink to &quot;0.4.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-10, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.4.0">GitHub release</a></p><div><h3 id="features-8" tabindex="-1">Features <a class="header-anchor" href="#features-8" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> add deepClean task that also removes frontend ca… (<a href="https://github.com/nijasc/ktor-svelte/commit/ff09bd1d76a77727d3115b2c5b69e7ea056e1cba" target="_blank" rel="noreferrer">ff09bd1</a>)</li><li><strong>gradle-plugin:</strong> add deepClean task that also removes frontend caches (<a href="https://github.com/nijasc/ktor-svelte/commit/01d736ce40bc15467e9695e810dd761a77d5c5e0" target="_blank" rel="noreferrer">01d736c</a>)</li><li><strong>gradle-plugin:</strong> svelteDoctor checks adapter output, bundled mani… (<a href="https://github.com/nijasc/ktor-svelte/commit/9ff4bbe87a5108a2f5855e8a6d8933aa9c33e325" target="_blank" rel="noreferrer">9ff4bbe</a>)</li><li><strong>gradle-plugin:</strong> svelteDoctor checks adapter output, bundled manifest and Node (<a href="https://github.com/nijasc/ktor-svelte/commit/b183f8a668089935f61c37b3132e9146690286fa" target="_blank" rel="noreferrer">b183f8a</a>)</li><li><strong>server:</strong> add local-only status endpoint (<a href="https://github.com/nijasc/ktor-svelte/commit/193b4b45a3ae9c45272461a5d9b90751322752da" target="_blank" rel="noreferrer">193b4b4</a>)</li><li><strong>server:</strong> add local-only status endpoint (<a href="https://github.com/nijasc/ktor-svelte/commit/c57cea365afd162c4c6042d6abd5b76a5a3c4014" target="_blank" rel="noreferrer">c57cea3</a>)</li><li><strong>server:</strong> add paramRoutes to serve the fallback for SvelteKit par… (<a href="https://github.com/nijasc/ktor-svelte/commit/0b5f298f7a2c41f4a4bef224c8ba9105b4c1fb97" target="_blank" rel="noreferrer">0b5f298</a>)</li><li><strong>server:</strong> add paramRoutes to serve the fallback for SvelteKit param routes (<a href="https://github.com/nijasc/ktor-svelte/commit/a28fd5556f66aa64476713f255745436fcb20c3d" target="_blank" rel="noreferrer">a28fd55</a>)</li><li><strong>server:</strong> forward POST, PUT, PATCH and DELETE through the dev proxy (<a href="https://github.com/nijasc/ktor-svelte/commit/7dd6a14061a7ae338b5ba05e0156eb8c04669192" target="_blank" rel="noreferrer">7dd6a14</a>)</li><li><strong>server:</strong> forward POST, PUT, PATCH and DELETE through the dev proxy (<a href="https://github.com/nijasc/ktor-svelte/commit/548997d9275e70d9c7224106bfcc23c3562f8733" target="_blank" rel="noreferrer">548997d</a>)</li><li><strong>server:</strong> generate async generator helpers for event stream routes (<a href="https://github.com/nijasc/ktor-svelte/commit/b5ccb07aebfdba1f7113e83f39d1e21cec158dcc" target="_blank" rel="noreferrer">b5ccb07</a>)</li><li><strong>server:</strong> generate async generator helpers for event stream routes (<a href="https://github.com/nijasc/ktor-svelte/commit/915f3f34fd9b084c24aa11297d9d526d9718c991" target="_blank" rel="noreferrer">915f3f3</a>)</li><li><strong>server:</strong> generate TypeScript enums as const objects (<a href="https://github.com/nijasc/ktor-svelte/commit/7e99038a889d21ff0053585cc2173d3acd5c0bef" target="_blank" rel="noreferrer">7e99038</a>)</li><li><strong>server:</strong> generate TypeScript enums as const objects (<a href="https://github.com/nijasc/ktor-svelte/commit/87390fa5836ab84301e9a036567341c2ffd6560b" target="_blank" rel="noreferrer">87390fa</a>)</li></ul></div><h2 id="_0-3-1" tabindex="-1">0.3.1 <a class="header-anchor" href="#_0-3-1" aria-label="Permalink to &quot;0.3.1&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-10, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.3.1">GitHub release</a></p><div><h3 id="bug-fixes-8" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-8" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>server:</strong> encode unsafe characters in dev proxy request paths (<a href="https://github.com/nijasc/ktor-svelte/commit/64c1403f39f9fa75c570f12d1c94987b0559c090" target="_blank" rel="noreferrer">64c1403</a>)</li><li><strong>server:</strong> encode unsafe characters in dev proxy request paths (<a href="https://github.com/nijasc/ktor-svelte/commit/0045ba7d66b1cea3ade2ecfc1945fdeff90e08e9" target="_blank" rel="noreferrer">0045ba7</a>)</li></ul></div><h2 id="_0-3-0" tabindex="-1">0.3.0 <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to &quot;0.3.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-03, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.3.0">GitHub release</a></p><div><h3 id="features-9" tabindex="-1">Features <a class="header-anchor" href="#features-9" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>repo:</strong> add project setup options and move the scripts to scripts/ (<a href="https://github.com/nijasc/ktor-svelte/commit/4cda4579a7209cece8aee264bc00ceabed2d9474" target="_blank" rel="noreferrer">4cda457</a>)</li><li><strong>repo:</strong> add project setup options and move the scripts to scripts/ (<a href="https://github.com/nijasc/ktor-svelte/commit/2de0e5e0d09994cd0038b7356e05b3ff01b074d5" target="_blank" rel="noreferrer">2de0e5e</a>)</li><li><strong>repo:</strong> add setup questions for sign in, Postgres, Flyway, IntelliJ and CI (<a href="https://github.com/nijasc/ktor-svelte/commit/a48cd933b405b52fa42538f80863df940210be2d" target="_blank" rel="noreferrer">a48cd93</a>)</li></ul></div><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-03, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.2.0">GitHub release</a></p><div><h3 id="features-10" tabindex="-1">Features <a class="header-anchor" href="#features-10" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>add frontend libraries, a project installer and README badges (<a href="https://github.com/nijasc/ktor-svelte/commit/e71092ea624f0e30e05ccefb7f62884ee034690b" target="_blank" rel="noreferrer">e71092e</a>)</li><li><strong>example:</strong> use all frontend libraries in the notes app (<a href="https://github.com/nijasc/ktor-svelte/commit/bdc25c30e2ae9730eda6496973f827631c6a0c55" target="_blank" rel="noreferrer">bdc25c3</a>)</li><li><strong>gradle-plugin:</strong> configure Tailwind, DaisyUI, Lucide and i18n from Gradle (<a href="https://github.com/nijasc/ktor-svelte/commit/9d74b1df8d207bd71dbcd863c6d083f90fbf73bc" target="_blank" rel="noreferrer">9d74b1d</a>)</li><li><strong>repo:</strong> add a one-command installer that creates a new project (<a href="https://github.com/nijasc/ktor-svelte/commit/f4ed7f1926c8a74ffee71cdb56e8f6dfa8355c51" target="_blank" rel="noreferrer">f4ed7f1</a>)</li><li><strong>server:</strong> add svelteLocale, svelteTheme and locale prefix redirects (<a href="https://github.com/nijasc/ktor-svelte/commit/9d74b1df8d207bd71dbcd863c6d083f90fbf73bc" target="_blank" rel="noreferrer">9d74b1d</a>)</li></ul><h3 id="bug-fixes-9" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-9" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> find tools when PATH entries have spaces or quotes (<a href="https://github.com/nijasc/ktor-svelte/commit/7533a1c2faf9a49897f1356380ab58bc77649297" target="_blank" rel="noreferrer">7533a1c</a>)</li><li><strong>gradle-plugin:</strong> generate Kotlin that passes ktlint (<a href="https://github.com/nijasc/ktor-svelte/commit/f4868990bef0215122c545c5caa831791698e02f" target="_blank" rel="noreferrer">f486899</a>)</li><li><strong>gradle-plugin:</strong> generate Kotlin that passes ktlint (<a href="https://github.com/nijasc/ktor-svelte/commit/0e7987d2a400c7555201d60d1d1cab62cc2b9921" target="_blank" rel="noreferrer">0e7987d</a>)</li></ul></div><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><p class="changelog-meta">Released 2026-11-03, <a href="https://github.com/nijasc/ktor-svelte/releases/tag/v0.1.0">GitHub release</a></p><div><h3 id="features-11" tabindex="-1">Features <a class="header-anchor" href="#features-11" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>example:</strong> add basic app with an end-to-end JAR test (<a href="https://github.com/nijasc/ktor-svelte/commit/f288e9fb20ae22428ae5035c9d795efc8f51325c" target="_blank" rel="noreferrer">f288e9f</a>)</li><li><strong>example:</strong> add notes app with generated client, CRUD and transport (<a href="https://github.com/nijasc/ktor-svelte/commit/bf86c942027bea14da29905479a50815876f34e7" target="_blank" rel="noreferrer">bf86c94</a>)</li><li><strong>gradle-plugin:</strong> add frontend utility tasks and IntelliJ run configurations (<a href="https://github.com/nijasc/ktor-svelte/commit/0d0607738fde8dbb04d19b4aa6015840dc556e21" target="_blank" rel="noreferrer">0d06077</a>)</li><li><strong>gradle-plugin:</strong> add svelteDevAll to run everything with one command (<a href="https://github.com/nijasc/ktor-svelte/commit/72aba119e67bc5ba65b691f54c64eb7def90c52a" target="_blank" rel="noreferrer">72aba11</a>)</li><li><strong>gradle-plugin:</strong> add svelteInit and svelteDoctor (<a href="https://github.com/nijasc/ktor-svelte/commit/4be840231a0894b437c7ab74cbcb407cc0be4b4b" target="_blank" rel="noreferrer">4be8402</a>)</li><li><strong>gradle-plugin:</strong> build the frontend and package it into the JAR (<a href="https://github.com/nijasc/ktor-svelte/commit/caf5449a294e6b64a652357137b452c78785b1e5" target="_blank" rel="noreferrer">caf5449</a>)</li><li><strong>gradle-plugin:</strong> set up a short #api import for the generated client (<a href="https://github.com/nijasc/ktor-svelte/commit/d64221496056e28817ffabef1dec351384b7ad30" target="_blank" rel="noreferrer">d642214</a>)</li><li><strong>server:</strong> add API docs, security headers, runtime config and protected routes (<a href="https://github.com/nijasc/ktor-svelte/commit/4b88d975f3d732fe5db788347f87f114378dd262" target="_blank" rel="noreferrer">4b88d97</a>)</li><li><strong>server:</strong> add typed API errors and form validation (<a href="https://github.com/nijasc/ktor-svelte/commit/9fe0b1e8f79c6d3f7aed8f9792b0b162c0c114d1" target="_blank" rel="noreferrer">9fe0b1e</a>)</li><li><strong>server:</strong> configure JSON, XML and compression inside install(Svelte) (<a href="https://github.com/nijasc/ktor-svelte/commit/03b17054a1bfc0ce982488f6c88c792e202f96a3" target="_blank" rel="noreferrer">03b1705</a>)</li><li><strong>server:</strong> define validation rules on request classes with Validated (<a href="https://github.com/nijasc/ktor-svelte/commit/38f2029605d8ec0a9aceeba9c7f4cc4083382d88" target="_blank" rel="noreferrer">38f2029</a>)</li><li><strong>server:</strong> generate TypeScript types and services from Ktor routes (<a href="https://github.com/nijasc/ktor-svelte/commit/03b17054a1bfc0ce982488f6c88c792e202f96a3" target="_blank" rel="noreferrer">03b1705</a>)</li><li><strong>server:</strong> proxy frontend requests to Vite in development mode (<a href="https://github.com/nijasc/ktor-svelte/commit/27621b3dcc2bb3e1d3b383fdb21296a2f53ed22a" target="_blank" rel="noreferrer">27621b3</a>)</li><li><strong>server:</strong> serve SvelteKit builds through a Ktor plugin (<a href="https://github.com/nijasc/ktor-svelte/commit/0e65aed13fa2ff15705469f68df5689736855b20" target="_blank" rel="noreferrer">0e65aed</a>)</li><li>validate on request classes, add #api import, fix release blockers (<a href="https://github.com/nijasc/ktor-svelte/commit/dbf8dcfd4309e864c2d7e19bb43c7c721a38d5d0" target="_blank" rel="noreferrer">dbf8dcf</a>)</li></ul><h3 id="bug-fixes-10" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-10" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>gradle-plugin:</strong> keep hidden files and source maps out of the JAR (<a href="https://github.com/nijasc/ktor-svelte/commit/e804d8eaf2cd9ec3923a901f844eb4ac639bdbe3" target="_blank" rel="noreferrer">e804d8e</a>)</li><li><strong>server:</strong> exit cleanly after generating TypeScript with svelteGenerateTs (<a href="https://github.com/nijasc/ktor-svelte/commit/594c63ba8100f6181a48fdb22142889c0b58b3b0" target="_blank" rel="noreferrer">594c63b</a>)</li><li><strong>server:</strong> restrict the dev proxy to this machine and protect private pages (<a href="https://github.com/nijasc/ktor-svelte/commit/625f004918d1caab88fff502600aa30bba1f9352" target="_blank" rel="noreferrer">625f004</a>)</li></ul><h3 id="build-system" tabindex="-1">Build System <a class="header-anchor" href="#build-system" aria-label="Permalink to &quot;Build System&quot;">​</a></h3><ul><li><strong>repo:</strong> make the first release 0.1.0 (<a href="https://github.com/nijasc/ktor-svelte/commit/c5d1b524217c73ee6517edbd89a3a1ca93427a5f" target="_blank" rel="noreferrer">c5d1b52</a>)</li></ul></div>',50)])])}const h=r(o,[["render",i]]);export{d as __pageData,h as default};
